from scipy.optimize import least_squares
def mk(form):
    def model(p,t,P):
        k=p[0]
        if form=='tanh': g=np.tanh(k*t)
        elif form=='exp': g=1-np.exp(-k*t)
        elif form=='hyp': g=t/(k+t)
        elif form=='sig': g=1/(1+np.exp(-k*(t-p[1])))
        return g
    return model
def run(form,npar):
    mdl=mk(form)
    def res(p):
        g=mdl(p,t,P)
        A=p[npar+0]; B0=p[npar+1]; B1=p[npar+2]; C=p[npar+3]; D=p[npar+4]
        # dP = A*g + (B0+B1*g)*P + C*P^2 + D*P^3
        pred=A*g+(B0+B1*g)*P+C*P**2+D*P**3
        return pred-dP_dt
    best=None
